          : this.currentStreakDays,
      longestStreakDays: data.longestStreakDays.present
          ? data.longestStreakDays.value
          : this.longestStreakDays,
      freezeCount: data.freezeCount.present
          ? data.freezeCount.value
          : this.freezeCount,
